def label_encode(s):
    """Label-encode a categorical Series into integer codes."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Map each
    # distinct value to its first-seen integer index and return the code list."
    mp = {}
    res = []
    for v in s:
        if v not in mp:
            mp[v] = len(mp)
        res.append(mp[v])
    return res


def one_hot_encode(s):
    """One-hot encode a categorical Series into an indicator DataFrame."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Build a
    # DataFrame with one indicator column per distinct value of the Series."
    lev = []
    for v in s:
        if v not in lev:
            lev.append(v)
    rows = []
    for v in s:
        rows.append([1 if v == l else 0 for l in lev])
    return pd.DataFrame(rows, columns=["%s_%s" % (s.name, l) for l in lev])


