def minkowski(x, y, p):
    """Compute the Minkowski distance of order p between two vectors."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Vectorize
    # the Minkowski sum with numpy: sum of |xi-yi|**p, then the p-th root."
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    return float(np.sum(np.abs(x - y) ** p) ** (1.0 / p))


