def dot(a, b):
    """Compute the dot product of two vectors."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Return
    # the element-wise product sum, vectorized with numpy."
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    return float(np.sum(a * b))


def euc_len(a):
    """Compute the Euclidean norm of a vector."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Return
    # the square root of the sum of squares, vectorized with numpy."
    a = np.asarray(a, dtype=float)
    return float(np.sqrt(np.sum(a * a)))


