def mean(s):
    """Compute the mean of a set of values, ignoring NaN values."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Filter
    # NaN values and return the arithmetic mean."
    s = [v for v in s if v == v]
    return sum(s) / len(s)


def variance(s):
    """Compute the population variance of a set of values."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Return
    # the mean of the squared deviations from the mean. This matches the
    # student's Lab03 behavior exactly (no NaN filter inside variance)."
    mu = mean(s)
    res = 0
    for v in s:
        res += (v - mu) ** 2
    return res / len(s)


def std_dev(s):
    """Compute the population standard deviation of a set of values."""
    # Generated by DeepSeek-V4-Flash-0731 (via custom pi harness) - "Return
    # the square root of the variance."
    return variance(s) ** 0.5


